# Check if rlm is available as a module or built-in
import sys
for name in ['rlm', 'finish']:
    if name in globals():
        print(f"Found {name} in globals: {globals()[name]}")
    if name in locals():
        print(f"Found {name} in locals: {locals()[name]}")
    if name in dir(__builtins__):
        print(f"Found {name} in builtins: {getattr(__builtins__, name)}")

# Check all modules loaded
for mod_name in list(sys.modules.keys()):
    if 'rlm' in mod_name.lower():
        print(f"Module with 'rlm': {mod_name}")

# Try importing rlm
try:
    import rlm
    print(f"Imported rlm: {rlm}")
    if hasattr(rlm, 'finish'):
        print(f"rlm.finish exists: {rlm.finish}")
except ImportError:
    print("Cannot import rlm")
